(function(){const n=document.createElement("link").relList;if(n&&n.supports&&n.supports("modulepreload"))return;for(const t of document.querySelectorAll('link[rel="modulepreload"]'))i(t);new MutationObserver(t=>{for(const s of t)if(s.type==="childList")for(const u of s.addedNodes)u.tagName==="LINK"&&u.rel==="modulepreload"&&i(u)}).observe(document,{childList:!0,subtree:!0});function e(t){const s={};return t.integrity&&(s.integrity=t.integrity),t.referrerPolicy&&(s.referrerPolicy=t.referrerPolicy),t.crossOrigin==="use-credentials"?s.credentials="include":t.crossOrigin==="anonymous"?s.credentials="omit":s.credentials="same-origin",s}function i(t){if(t.ep)return;t.ep=!0;const s=e(t);fetch(t.href,s)}})();const $a=[{dir:"01-judol",cat:"Finansial",head:"Hampir jackpot itu memang sengaja dibikin.",chrome:"#07140C",pos:"42%",src:"Clark dkk. 2009 (Neuron); Dixon dkk., Univ. Waterloo (2010, 2013); PPATK (2024, 2025).",title:"Judol",slides:['Pernah lihat orang main slot terus teriak "Yah, dikit lagi!"? Habis itu biasanya top up lagi. Nah, momen "dikit lagi" itu ternyata ada ilmunya.',"Tahun 2009 ada peneliti yang ngecek otak orang lagi main slot. Waktu hampir menang, bagian otak yang nyala ternyata sama kayak waktu beneran menang duit.",'Lucunya, orang-orang ini bilang hampir menang itu lebih nyebelin daripada kalah telak. Tapi justru habis hampir menang, mereka paling pengen main lagi. Ada juga studi yang nemuin pemain langsung spin lagi secepat mungkin habis "dikit lagi".',"Terus, itu kebetulan? Peneliti di Kanada pernah dapat dokumen desain mesin slot. Di situ, momen hampir menang memang udah diatur dari awal. Judol yang bentuknya slot pakai pola yang sama.",'Jadi kalau kamu atau temanmu ngerasa "tinggal dikit lagi nih", ya itu memang perasaan yang lagi dijual. Ujung-ujungnya yang untung tetap bandar.'],deep:`<h2>Judol, lebih dalam</h2>
<h3>Menang tapi tekor</h3>
<p>Ada trik lain yang lebih licik. Misalnya kamu pasang Rp10.000, terus "menang" Rp3.000. Mesinnya bunyi heboh, lampunya kedip-kedip, rasanya kayak menang. Padahal duitmu kurang Rp7.000. Penelitian di Kanada nemuin efek suara kayak gini bikin pemain ngira mereka lebih sering menang dari kenyataannya.</p>
<p>Di Indonesia sendiri, PPATK nyatat perputaran duit judol sepanjang 2025 tembus Rp286,84 triliun. Itu udah turun sekitar 20% dari tahun sebelumnya, tapi ya tetap aja angkanya gila. Yang main juga kebanyakan bukan orang berduit. Data PPATK tahun 2024, sekitar 7 dari 10 pemain judol penghasilannya di bawah Rp5 juta sebulan.</p>
<p class="src">Sumber: Clark dkk. 2009 (Neuron); Dixon dkk., Univ. Waterloo (2010, 2013); PPATK (2024, 2025).</p>`,quizzes:[{q:'Menurut studi, momen "hampir menang" di otak...',opts:["Diabaikan otak","Mengaktifkan area yang sama dengan saat menang","Bikin orang langsung berhenti","Gak berpengaruh apa-apa"],ans:1,why:"Penelitian tahun 2009 menemukan momen hampir menang menyalakan bagian otak yang sama dengan saat menang uang, makanya orang terdorong main lagi."},{q:"Hampir menang membuat pemain merasa...",opts:["Senang dan puas","Lebih gak enak dari kalah telak, tapi lebih pengen main lagi","Bosan","Ingin berhenti"],ans:1,why:"Anehnya dua-duanya kejadian bareng. Hampir menang terasa lebih nyebelin daripada kalah telak, tapi justru habis itu pemain paling pengen main lagi."},{q:'Taruhan Rp10.000 lalu "menang" Rp3.000 dengan suara heboh. Sebenarnya kamu...',opts:["Untung Rp3.000","Rugi Rp7.000","Impas","Untung Rp13.000"],ans:1,why:"Kamu keluar Rp10.000 dan cuma dapat balik Rp3.000. Suara heboh dan animasinya bikin kerasa menang, padahal kamu rugi Rp7.000."}]},{dir:"03-hoaks",cat:"Psikologi",head:"Hoaks yang sering kamu lihat lama-lama kerasa benar.",chrome:"#1A1222",pos:"62%",src:"Pennycook dkk. 2018; Fazio dkk. 2015; Brashier dkk. 2020.",title:"Hoaks",slides:['Pernah gak, dapat broadcast di grup keluarga, awalnya kamu ketawa karena jelas ngaco. Terus seminggu kemudian dapat lagi dari grup lain, lalu lagi. Lama-lama kok kepikiran, "Jangan-jangan bener ya?"',"Itu bukan karena kamu gampang dibohongi. Para peneliti nyebutnya illusory truth effect: info yang diulang-ulang bakal kerasa makin benar.",'Penyebabnya, otak lebih gampang memproses hal yang udah pernah dia lihat. Rasa "gampang" itu diam-diam dianggap tanda kalau infonya benar.','Tahun 2018 ada penelitian pakai judul berita hoaks asli dari Facebook. Cukup lihat sekali, orang udah lebih percaya waktu ketemu judul itu lagi, dan efeknya masih kerasa seminggu kemudian. Bahkan judul yang udah dikasih label "dibantah pemeriksa fakta" pun tetap kena efek ini.',"Yang lebih nyebelin, tahu jawaban yang benar pun gak sepenuhnya melindungi. Ada penelitian yang nemuin efek ini tetap muncul walaupun pesertanya sebenarnya udah tahu faktanya."],deep:`<h2>Hoaks, lebih dalam</h2>
<h3>Terus gimana ngelawannya?</h3>
<p>Ada satu trik yang ternyata ampuh di penelitian: langsung tanya ke diri sendiri "ini bener gak sih?" waktu pertama kali lihat infonya.</p>
<p>Dalam penelitian tahun 2020, peserta yang diminta menilai benar-salahnya sebuah klaim sejak pertama kali lihat, gak kena efek ini waktu ketemu klaim yang sama lagi. Efek perlindungannya masih ada dua hari kemudian.</p>
<p>Tapi ada syaratnya: trik ini cuma jalan kalau kamu punya sedikit pengetahuan soal topiknya. Kalau topiknya asing banget, ya tetap harus dicek ke sumber.</p>
<p class="src">Sumber: Pennycook dkk. 2018; Fazio dkk. 2015; Brashier dkk. 2020.</p>`,quizzes:[{q:"Kenapa hoaks yang diulang-ulang terasa benar?",opts:["Karena biasanya memang benar","Karena info yang sering dilihat lebih gampang diproses otak, dan rasa gampang itu dikira tanda benar","Karena yang ngirim orang terdekat","Karena hoaksnya panjang"],ans:1,why:"Info yang sering dilihat lebih gampang diproses otak, dan rasa gampang itu diam-diam dianggap tanda benar."},{q:'Label "dibantah pemeriksa fakta" pada judul hoaks...',opts:["Menghilangkan efeknya sepenuhnya","Tidak cukup untuk menghentikan efeknya","Membuat hoaks makin dipercaya","Tidak pernah diteliti"],ans:1,why:"Di penelitian 2018, judul yang udah dikasih label itu tetap lebih dipercaya setelah dilihat berulang kali."},{q:"Trik yang terbukti membantu di penelitian adalah...",opts:["Membaca hoaksnya berkali-kali",'Langsung menilai "ini benar gak?" waktu pertama kali lihat',"Membagikannya dulu baru dicek","Mengabaikan semua berita"],ans:1,why:"Di penelitian 2020, peserta yang langsung menilai benar atau salah sejak awal gak kena efek ini waktu ketemu klaim yang sama lagi. Syaratnya, kamu perlu sedikit paham soal topiknya."}]},{dir:"04-prokrastinasi",cat:"Psikologi",head:"Nunda skripsi itu bukan soal malas.",chrome:"#140716",pos:"55%",src:"Sirois & Pychyl, model temporal mood regulation; Wohl, Pychyl & Bennett 2010 (Personality and Individual Differences).",title:"Prokrastinasi",slides:["Niatnya buka laptop mau ngerjain bab 2. Sepuluh menit kemudian malah lagi nonton orang masak mi instan pakai cara aneh. Padahal tadi gak lapar. Pernah?","Ada dua peneliti, Tim Pychyl dan Fuschia Sirois, yang udah lama banget neliti soal nunda-nunda ini. Kata mereka, akar masalahnya bukan di waktu. Akarnya di perasaan.","Coba diingat, waktu buka file skripsi rasanya gimana? Bisa bosan, cemas, takut tulisannya jelek, takut dicoret dosbing. Otak gak suka rasa itu, jadi dia nyari jalan keluar paling cepat: kabur ke HP.","Dan memang langsung lega. Tapi ya cuma sebentar. Tugasnya masih ada, deadline makin dekat, dan ujung-ujungnya malah makin stres.","Makanya bikin jadwal serapi apa pun sering gak mempan. Pychyl sendiri bilang ngatur waktu itu perlu, cuma gak cukup. Yang perlu dibereskan duluan ya perasaannya."],deep:`<h2>Prokrastinasi, lebih dalam</h2>
<h3>Maafin diri sendiri itu ada gunanya</h3>
<p>Ada studi yang ngikutin mahasiswa selama dua kali UTS. Yang bisa maafin dirinya habis nunda belajar di ujian pertama, cenderung lebih jarang nunda waktu persiapan ujian kedua. Apalagi kalau nundanya di ujian pertama parah.</p>
<p>Kenapa bisa gitu? Nyalahin diri terus-terusan itu juga bikin perasaan gak enak. Akhirnya tugasnya makin kerasa berat, dan kita makin pengen kabur.</p>
<p>Yang bisa dicoba:</p>
<ul><li>Pas mau kabur ke HP, coba tanya ke diri sendiri: "Sebenarnya aku lagi ngerasa apa sih?"</li><li>Bilang ke diri sendiri, "Lima menit aja." Biasanya yang paling berat itu mulainya.</li><li>Kemarin nunda? Ya udah. Gak usah dihukum, lanjut aja hari ini.</li></ul>
<p class="src">Sumber: Sirois &amp; Pychyl, model temporal mood regulation; Wohl, Pychyl &amp; Bennett 2010 (Personality and Individual Differences).</p>`,quizzes:[{q:"Menurut riset, prokrastinasi paling tepat disebut masalah...",opts:["Manajemen waktu","Mengatur emosi","Kurang disiplin","Kurang tidur"],ans:1,why:"Menunda itu cara kabur dari perasaan tidak enak soal tugas. Jadi akarnya di emosi, bukan di waktu."},{q:"Kenapa menunda tugas terasa enak?",opts:["Karena otak butuh istirahat","Karena rasa tidak enak soal tugasnya langsung hilang, walaupun cuma sebentar","Karena deadline jadi terasa lebih jauh","Karena kita lebih kreatif di bawah tekanan"],ans:1,why:"Kabur ke HP bikin rasa bosan dan cemas soal tugas langsung hilang. Masalahnya cuma sebentar, karena tugasnya tetap ada dan deadline makin dekat."},{q:"Kenapa bikin jadwal super rapi sering gagal mengatasi prokrastinasi?",opts:["Jadwalnya terlalu panjang","Jadwalnya beres, tapi emosi terhadap tugasnya belum tersentuh","Orang malas membaca jadwal","Jadwal bikin stres"],ans:1,why:"Akar masalahnya di perasaan, bukan di waktu. Kata Pychyl, ngatur waktu itu perlu tapi gak cukup."}]},{dir:"05-jakarta",cat:"Sains",head:"Jakarta tenggelam, tapi bukan gara-gara laut naik.",chrome:"#081413",pos:"58%",src:"IPB; ITB; C40; peneliti UI; PAM Jaya.",title:"Jakarta tenggelam",slides:["Tiap ada berita banjir rob di Jakarta Utara, yang biasanya disalahin perubahan iklim dan air laut yang naik. Itu memang ada, tapi ternyata bukan pelaku utamanya.","Air laut di sekitar Jakarta naiknya sekitar 3 sampai 4 milimeter setahun. Sementara tanah Jakarta turunnya bisa 1 sampai 11 sentimeter setahun, tergantung lokasinya. Di beberapa titik malah lebih parah lagi.","Coba bandingin: milimeter lawan sentimeter. Tanahnya turun kira-kira sepuluh kali lebih cepat dari lautnya naik.","Penyebab utamanya, air tanah disedot terus-terusan. Air ledeng belum menjangkau semua warga. Perkiraannya baru sekitar setengah sampai 60% rumah tangga. Jadi banyak rumah, gedung, dan pabrik ngebor sumur sendiri. Begitu air di bawah tanah habis disedot, lapisan tanahnya memadat dan ambles.","Kabar baiknya, karena ini ulah manusia, masih bisa dikurangi. Beberapa studi bilang lajunya di sebagian wilayah mulai melambat, walaupun angkanya masih diperdebatkan."],deep:`<h2>Jakarta tenggelam, lebih dalam</h2>
<h3>Kenapa susah berhenti nyedot air tanah?</h3>
<p>Masalahnya muter. Air ledeng belum nyampe ke semua orang. Di gedung-gedung yang udah kebagian pun, kualitasnya sering dikeluhkan dan dianggap mahal. Jadi banyak yang tetap ngebor sumur dalam, sebagian diam-diam tanpa izin. Makin banyak yang nyedot, tanahnya makin ambles, dan risiko banjir rob makin besar.</p>
<p>Ini juga bikin kita sadar: tanggul laut doang gak cukup kalau tanah di belakangnya terus turun.</p>
<p class="src">Sumber: IPB; ITB; C40; peneliti UI; PAM Jaya.</p>`,quizzes:[{q:"Mana yang lebih cepat di Jakarta?",opts:["Naiknya air laut","Turunnya tanah","Sama cepatnya","Dua-duanya tidak berubah"],ans:1,why:"Tanahnya turun 1 sampai 11 sentimeter setahun, sedangkan laut naik sekitar 3 sampai 4 milimeter. Tanahnya kira-kira sepuluh kali lebih cepat."},{q:"Penyebab utama tanah Jakarta turun adalah...",opts:["Gempa bumi","Air tanah yang disedot terus-terusan","Gedung yang terlalu tinggi","Hujan deras"],ans:1,why:"Begitu air di bawah tanah disedot terus, lapisan tanahnya memadat dan permukaannya ikut turun."},{q:"Kenapa banyak warga dan gedung masih menyedot air tanah?",opts:["Karena air tanah lebih bersih","Karena air ledeng belum menjangkau semua dan sering dianggap kurang bagus","Karena diwajibkan pemerintah","Karena gratis dari PDAM"],ans:1,why:"Air ledeng baru menjangkau sekitar setengah sampai 60% rumah tangga, dan di tempat yang udah kebagian pun kualitasnya sering dikeluhkan. Jadi banyak yang tetap ngebor sumur sendiri."}]},{dir:"06-komodo",cat:"Sains",head:"Gigitan komodo mematikan, tapi bukan karena ludahnya kotor.",chrome:"#1C0C03",pos:"55%",src:"Fry dkk. 2009 (PNAS); Auffenberg 1981; Moreno & Wroe 2008.",title:"Komodo",slides:["Dulu kita diajarin: ludah komodo penuh bakteri, jadi mangsa yang digigit lama-lama mati karena infeksi. Cerita ini ada di buku, dokumenter, bahkan dipercaya dokter.","Ternyata cerita itu sebagian besar berawal dari satu sumber: buku seorang peneliti tahun 1981, hasil pengamatannya di lapangan pada tahun 1970-an.","Tahun 2009, tim peneliti dari Australia nge-scan kepala komodo pakai MRI. Mereka nemuin dua kelenjar bisa panjang di rahang bawahnya.","Bisanya bikin darah susah membeku dan bisa bikin mangsa syok. Jadi mangsa yang digigit terus berdarah dan cepat lemas.","Bakterinya gimana? Waktu mulut komodo diperiksa, mereka gak nemuin bakteri mematikan yang khas. Mulutnya ya kurang lebih kayak hewan pemakan daging lain."],deep:`<h2>Komodo, lebih dalam</h2>
<h3>Gigitannya justru lemah</h3>
<p>Ini yang bikin kaget: kekuatan gigitan komodo itu lemah. Di studi yang sama, gigitannya diperkirakan sekitar 6,5 kali lebih lemah dibanding buaya muara dengan ukuran tengkorak yang mirip.</p>
<p>Terus cara dia ngebunuh gimana? Komodo gigit, terus narik kepalanya ke belakang pakai otot leher yang kuat. Giginya bergerigi kayak gergaji, jadi lukanya dalam dan sobek. Ditambah bisa yang bikin darah susah beku, mangsanya cepat lemas.</p>
<p>Masih ada peneliti yang ragu seberapa besar peran bisanya dibanding luka sobeknya. Tapi teori ludah penuh bakteri udah ditinggalkan.</p>
<p class="src">Sumber: Fry dkk. 2009 (PNAS); Auffenberg 1981; Moreno &amp; Wroe 2008.</p>`,quizzes:[{q:"Menurut riset 2009, apa yang bikin gigitan komodo mematikan?",opts:["Bakteri di ludahnya","Luka sobek yang dalam ditambah bisa yang bikin darah susah beku","Gigitan yang sangat kuat","Racun di kukunya"],ans:1,why:"Riset 2009 menemukan kelenjar bisa yang bikin darah susah membeku. Ditambah luka sobek dari gigi bergerigi, mangsa cepat lemas. Teori ludah penuh bakteri sudah ditinggalkan."},{q:"Dibanding buaya dengan ukuran tengkorak mirip, gigitan komodo...",opts:["Jauh lebih kuat","Jauh lebih lemah","Sama kuatnya","Belum pernah diukur"],ans:1,why:"Gigitan komodo diperkirakan sekitar 6,5 kali lebih lemah dibanding buaya muara dengan ukuran tengkorak yang mirip. Senjatanya gigi bergerigi dan bisa, bukan tenaga gigitan."},{q:'Mitos "ludah penuh bakteri" sebagian besar berawal dari...',opts:["Penelitian MRI","Satu buku pengamatan lapangan tahun 1981","Cerita warga Pulau Komodo","Film dokumenter"],ans:1,why:"Sumbernya buku seorang peneliti tahun 1981 dari pengamatan lapangan di tahun 1970-an. Riset 2009 kemudian menemukan kelenjar bisa."}]},{dir:"07-pulau-run",cat:"Sejarah",head:"Pulau kecil di Maluku pernah “ditukar” dengan Manhattan.",chrome:"#170803",pos:"50%",src:"Perjanjian Breda 1667; Perjanjian Westminster 1654; Cambridge World History of Genocide.",title:"Pulau Run",slides:["Sekarang Manhattan isinya gedung pencakar langit dan Wall Street. Tapi tahun 1600-an, Belanda malah lebih ngotot mempertahankan pulau mungil di Maluku namanya Pulau Run.","Alasannya satu: pala. Pala dan bunga pala waktu itu cuma tumbuh di Kepulauan Banda. Di Eropa, rempah ini mahal banget dan jadi rebutan.","Belanda lewat VOC pengen menguasai semua pala di dunia. Masalahnya, Inggris udah lebih dulu punya pijakan di Pulau Run. Selama Run masih dipegang Inggris, monopoli Belanda gak bakal sempurna.","Inggris dan Belanda perang beberapa kali. Tahun 1667, mereka tanda tangan Perjanjian Breda. Hasilnya: Inggris melepas klaimnya atas Run, dan Belanda melepas klaimnya atas Nieuw Amsterdam, kota kecil yang belakangan berganti nama jadi New York.","Jadi waktu itu, buat Belanda, pulau penghasil pala jauh lebih berharga daripada sebuah kota di Amerika."],deep:`<h2>Pulau Run, lebih dalam</h2>
<h3>Harga mahal di balik pala</h3>
<p>Ada sisi gelap dari cerita ini. Tahun 1621, sebelum Breda, VOC di bawah Jan Pieterszoon Coen menyerbu Kepulauan Banda supaya bisa menguasai pala sepenuhnya.</p>
<p>Ribuan orang Banda tewas, banyak juga yang diperbudak, dan ada yang meninggal kelaparan setelah lari ke gunung. Para pemimpin lokal dieksekusi. Kebun-kebun pala lalu dibagi-bagi dan dikelola pendatang dengan tenaga budak. Sebagian sejarawan menyebut peristiwa ini sebagai genosida.</p>
<h3>"ditukar" itu sebenarnya penyederhanaan</h3>
<p>Di perjanjiannya gak ada tulisan "Run ditukar Manhattan". Prinsipnya, masing-masing pihak mempertahankan wilayah yang lagi mereka kuasai waktu perang selesai. Belanda waktu itu pegang Run, Inggris pegang Manhattan. Jadi ini lebih tepat disebut saling melepas klaim. Istilah "ditukar" muncul belakangan karena ceritanya lebih gampang diingat.</p>
<p class="src">Sumber: Perjanjian Breda 1667; Perjanjian Westminster 1654; Cambridge World History of Genocide.</p>`,quizzes:[{q:"Kenapa Belanda sangat menginginkan Pulau Run?",opts:["Ada tambang emas","Supaya bisa memonopoli pala","Untuk pelabuhan perang","Karena pemandangannya indah"],ans:1,why:"Pala waktu itu cuma tumbuh di Kepulauan Banda. Selama Inggris masih pegang Run, Belanda tidak bisa memonopoli pala."},{q:"Perjanjian Breda tahun 1667 menghasilkan...",opts:["Indonesia merdeka","Inggris melepas klaim atas Run, Belanda melepas klaim atas Manhattan","Belanda membeli Manhattan","VOC dibubarkan"],ans:1,why:"Isinya saling melepas klaim. Inggris melepas Run, Belanda melepas Nieuw Amsterdam yang belakangan jadi New York."},{q:"Apa yang terjadi di Banda tahun 1621?",opts:["Perjanjian damai","VOC menyerbu Banda, ribuan orang Banda tewas dan diperbudak","Gunung meletus","Pala pertama kali ditanam"],ans:1,why:"Di bawah Jan Pieterszoon Coen, VOC menyerbu Banda demi menguasai pala. Ribuan orang Banda tewas atau diperbudak, dan sebagian sejarawan menyebutnya genosida."}]},{dir:"08-paylater",cat:"Finansial",head:"Pakai paylater, belanjanya jadi makin banyak. Ada risetnya.",chrome:"#260914",pos:"18%",src:"Prelec & Loewenstein 1998; Di Maggio, Williams & Katz 2022 (NBER w30508).",title:"Paylater",slides:['Checkout keranjang Rp600 ribu. Kalau pakai transfer, mikir dua kali. Tapi begitu muncul tulisan "cicil Rp200 ribu × 3, bunga 0%", tiba-tiba kerasa ringan. Klik.','Para ahli ekonomi perilaku punya istilah buat ini: pain of paying, alias rasa "sakit" waktu ngeluarin duit. Rasa sakit ini sebenarnya berguna, karena dia yang bikin kita ngerem.',"Masalahnya, sakitnya beda-beda tergantung cara bayar. Bayar tunai paling kerasa, karena duitnya kelihatan keluar dari dompet. Kartu kredit kurang kerasa. Nah, paylater bikin momen bayarnya jauh banget dari momen belanja.","Ini bukan cuma teori. Ada penelitian tahun 2022 dari ekonom di Amerika yang ngecek data transaksi asli. Hasilnya, setelah orang mulai pakai paylater, total belanjanya naik, dan tetap tinggi berbulan-bulan, terutama belanja ritel.","Jadi kalau ngerasa boros sejak pakai paylater, itu bukan cuma kamu kok. Cara bayarnya memang bikin rem kita kendor."],deep:`<h2>Paylater, lebih dalam</h2>
<h3>Bedanya teori dan temuan</h3>
<p>Perlu dicatat, para peneliti paylater itu sendiri gak bilang penyebabnya pasti "rasa sakit bayar" yang hilang. Mereka nyebutnya liquidity flypaper effect: duit tambahan yang muncul di satu tempat (di sini, limit paylater buat belanja online) cenderung "nempel" dan habis di tempat itu juga. Penjelasannya bisa jadi gabungan dua-duanya.</p>
<p>Yang bisa dicoba:</p>
<ul><li>Sebelum klik paylater, hitung total harganya, jangan lihat cicilannya.</li><li>Tanya ke diri sendiri: "Kalau harus bayar lunas sekarang, aku tetap beli gak?"</li><li>Matikan paylater sebagai metode bayar default di aplikasi belanja.</li></ul>
<p class="src">Sumber: Prelec &amp; Loewenstein 1998; Di Maggio, Williams &amp; Katz 2022 (NBER w30508).</p>`,quizzes:[{q:"Apa itu pain of paying?",opts:["Biaya admin saat bayar",'Rasa "sakit" waktu ngeluarin duit, yang bikin kita ngerem belanja',"Denda telat bayar","Pajak belanja online"],ans:1,why:'"Pain of paying" adalah rasa sakit waktu ngeluarin duit. Rasa ini yang bikin kita ngerem, dan paylater bikin rasanya makin tidak terasa.'},{q:'Cara bayar yang paling terasa "sakit" adalah...',opts:["Tunai","Kartu kredit","Paylater","Semuanya sama"],ans:0,why:"Waktu bayar tunai, duitnya kelihatan keluar dari dompet. Kartu kredit lebih gak kerasa, dan paylater paling gak kerasa."},{q:"Penelitian tahun 2022 menemukan bahwa setelah orang mulai pakai paylater...",opts:["Belanjanya turun","Total belanjanya naik dan tetap tinggi berbulan-bulan","Tidak ada perubahan","Mereka berhenti belanja online"],ans:1,why:"Penelitian itu pakai data transaksi asli. Setelah orang mulai pakai paylater, belanjanya naik dan tetap tinggi berbulan-bulan, terutama belanja ritel."}]},{dir:"09-earworm",cat:"Psikologi",head:"Lagu yang gak kamu suka nempel terus, materi ujian langsung lupa.",chrome:"#241703",pos:"22%",src:"Jakubowski dkk.; survei Finlandia 12.519 responden; Murre & Dros 2015; Roediger & Karpicke 2006.",title:"Earworm",slides:["Lagu yang lagi viral, yang sebenarnya kamu gak suka, malah muter terus di kepala dari pagi. Tapi materi yang kamu baca semalaman buat ujian, besoknya udah kosong. Gak adil banget ya.","Lagu yang nempel di kepala itu namanya earworm. Hampir semua orang ngalamin. Satu survei di Finlandia ke lebih dari 12 ribu orang nemuin sekitar 90% orang kena earworm minimal seminggu sekali.","Peneliti yang ngebandingin lagu yang sering nempel sama lagu yang gak nempel nemuin polanya: lagu yang nempel biasanya temponya cepat dan melodinya simpel, gampang diikuti.","Materi ujian? Beda cerita. Tahun 1880-an, peneliti Jerman namanya Hermann Ebbinghaus ngetes ingatannya sendiri dan nemuin kalau kita lupa paling cepat di awal-awal setelah belajar. Ini yang sekarang dikenal sebagai kurva lupa. Penelitian tahun 2015 yang ngulang percobaannya dapat hasil yang mirip.","Kabar baiknya, ada cara biar materi lebih nempel. Bukan dengan baca ulang terus-terusan, tapi dengan ngetes diri sendiri."],deep:`<h2>Earworm, lebih dalam</h2>
<h3>Ngetes diri sendiri lebih ampuh dari baca ulang</h3>
<p>Tahun 2006 ada eksperimen ke mahasiswa. Satu grup baca materi berkali-kali. Grup lain baca sekali, terus disuruh nginget-nginget isinya tanpa lihat catatan.</p>
<p>Dites lima menit kemudian, grup yang baca ulang menang. Tapi dites seminggu kemudian, hasilnya kebalik: grup yang nginget-nginget jauh lebih ingat.</p>
<p>Ditambah lagi, belajar yang dicicil dengan jeda biasanya lebih nempel dibanding dikebut sekaligus.</p>
<p>Itu juga alasannya app ini selalu kasih kuis di akhir, dan kuisnya muncul lagi beberapa hari kemudian.</p>
<p class="src">Sumber: Jakubowski dkk.; survei Finlandia 12.519 responden; Murre &amp; Dros 2015; Roediger &amp; Karpicke 2006.</p>`,quizzes:[{q:"Cara belajar yang bikin materi lebih lama diingat menurut eksperimen tahun 2006 adalah...",opts:["Baca ulang berkali-kali","Ngetes diri sendiri tanpa lihat catatan","Belajar sambil dengar musik","Belajar semalaman sebelum ujian"],ans:1,why:"Di eksperimen 2006, grup yang ngetes dirinya sendiri jauh lebih ingat seminggu kemudian dibanding grup yang cuma baca ulang."},{q:"Lagu yang gampang jadi earworm biasanya...",opts:["Lambat dan rumit","Temponya cepat dan melodinya simpel","Lagu yang paling kita suka","Lagu tanpa lirik"],ans:1,why:"Peneliti yang ngebandingin lagu yang nempel dan yang gak nempel nemuin pola ini. Lagu yang nempel biasanya cepat dan melodinya gampang diikuti."},{q:"Menurut kurva lupa, kapan kita paling cepat lupa?",opts:["Di awal-awal setelah belajar","Setelah sebulan","Setelah setahun","Kita tidak pernah lupa"],ans:0,why:"Ebbinghaus nemuin ingatan paling cepat hilang di awal setelah belajar. Makanya ngetes diri sendiri dan belajar dengan jeda bikin materi lebih nempel."}]},{dir:"10-krakatau",cat:"Sejarah",head:"Letusan Krakatau 1883 kedengaran sampai 4.800 km.",chrome:"#160603",pos:"62%",src:"Catatan resmi pemerintah Belanda; Olson dkk. 2004; Muri dkk. 2017.",title:"Krakatau",slides:["Agustus 1883, di Pulau Rodrigues dekat Mauritius, di tengah Samudra Hindia, warga dengar suara dentuman dari arah timur. Mereka kira itu bunyi meriam dari kapal yang lagi kesusahan.","Ternyata itu suara Krakatau meletus, dari jarak sekitar 4.800 kilometer. Kira-kira hampir sejauh Jakarta ke Tokyo.","Bukan cuma suaranya. Gelombang tekanan udaranya kecatat di alat pengukur tekanan di berbagai negara, dan muter ngelilingin bumi beberapa kali.","Di dekat Selat Sunda, korbannya luar biasa. Catatan resmi pemerintah Belanda waktu itu nyebut lebih dari 36 ribu orang tewas, kebanyakan karena tsunami yang nyapu pesisir Banten dan Lampung.","Abunya naik sampai ke lapisan atas atmosfer dan nyebar ke seluruh dunia. Langit di berbagai negara jadi merah menyala waktu matahari terbenam, dan suhu rata-rata dunia sempat turun selama beberapa tahun."],deep:`<h2>Krakatau, lebih dalam</h2>
<h3>Langit merah dan lukisan "The Scream"</h3>
<p>Ada teori yang bilang langit merah di lukisan terkenal The Scream karya Edvard Munch terinspirasi senja merah setelah letusan Krakatau. Waktu itu memang ada laporan langit senja aneh di Norwegia.</p>
<p>Tapi teori ini masih diperdebatkan. Peneliti dari Universitas Oslo punya penjelasan lain: Munch kemungkinan lihat awan langka yang warnanya kayak mutiara, yang memang pernah tercatat di Oslo. Jadi anggap aja ini misteri yang belum kepecahkan.</p>
<h3>Anaknya masih aktif</h3>
<p>Puluhan tahun setelah letusan 1883, muncul gunung baru dari laut di lokasi yang sama. Namanya Anak Krakatau.</p>
<p>Tanggal 22 Desember 2018, sebagian lereng Anak Krakatau longsor ke laut dan memicu tsunami di Selat Sunda. Lebih dari 400 orang tewas. Tsunami ini datang bukan karena gempa besar, makanya banyak orang gak sempat siap-siap.</p>
<p class="src">Sumber: Catatan resmi pemerintah Belanda; Olson dkk. 2004; Muri dkk. 2017.</p>`,quizzes:[{q:"Di Pulau Rodrigues, suara letusan Krakatau dikira...",opts:["Suara petir","Bunyi meriam kapal","Gempa bumi","Suara pesawat"],ans:1,why:"Warga Pulau Rodrigues, sekitar 4.800 km jauhnya, mengira dentuman itu bunyi meriam dari kapal."},{q:"Sebagian besar korban letusan 1883 tewas karena...",opts:["Abu panas","Tsunami","Gempa","Kelaparan"],ans:1,why:"Dari lebih dari 36 ribu korban, kebanyakan tewas karena tsunami yang menyapu pesisir Banten dan Lampung."},{q:"Tsunami Selat Sunda tahun 2018 dipicu oleh...",opts:["Gempa besar di laut","Longsornya lereng Anak Krakatau ke laut","Badai","Meteor"],ans:1,why:"Tanggal 22 Desember 2018, sebagian lereng Anak Krakatau longsor ke laut. Tsunaminya bukan dipicu gempa besar, jadi banyak orang gak sempat siap-siap."}]},{dir:"11-harga",cat:"Finansial",head:"Rp49.900 sama Rp50.000 cuma beda cepek. Kok kerasa jauh?",chrome:"#0C1603",pos:"55%",src:"Thomas & Morwitz 2005 (Journal of Consumer Research).",title:"Rp49.900",slides:['Lagi lihat menu, ada paket Rp49.900. Otak langsung nangkep "empat puluh ribuan". Padahal kalau dibulatin ya udah lima puluh ribu, bedanya cuma seratus perak.',"Ini namanya efek digit kiri. Waktu baca angka, otak kita nangkep angka paling kiri duluan, terus angka sisanya kurang diperhatiin.","Penelitian tahun 2005 di Amerika nemuin efek ini lewat lima eksperimen. Harga yang angka depannya turun, misalnya dari 3 jadi 2, kerasa lebih murah dari selisih aslinya.","Tapi efeknya ada syaratnya. Dia cuma jalan kalau angka paling kirinya beneran berubah. Rp49.900 vs Rp50.000 kena efeknya. Rp48.900 vs Rp49.000 nggak, karena angka depannya sama-sama 4.","Efeknya juga lebih kuat kalau kita lagi ngebandingin dua harga yang mirip, misalnya pas milih antara dua produk di rak."],deep:`<h2>Rp49.900, lebih dalam</h2>
<h3>Biar gak gampang kena</h3>
<p>Penelitian yang sama nemuin efek ini bukan cuma soal harga. Angka lain yang digitnya banyak juga bisa kena, misalnya spesifikasi atau ukuran.</p>
<p>Yang bisa dicoba:</p>
<ul><li>Biasain bulatin harga ke atas di kepala. Rp49.900 = Rp50.000. Rp1.999.000 = Rp2 juta.</li><li>Pas bandingin dua barang, lihat selisih aslinya, jangan cuma angka depannya.</li><li>Waspadai harga "tanggung" yang muncul di momen kita lagi ngebandingin, misalnya di halaman checkout atau rak promo.</li></ul>
<p class="src">Sumber: Thomas &amp; Morwitz 2005 (Journal of Consumer Research).</p>`,quizzes:[{q:"Kenapa Rp49.900 terasa jauh lebih murah dari Rp50.000?",opts:["Karena memang jauh lebih murah","Karena otak membaca angka paling kiri duluan","Karena ada diskon tersembunyi","Karena pajaknya beda"],ans:1,why:'Otak menangkap angka paling kiri duluan, jadi Rp49.900 terasa "empat puluh ribuan" walaupun cuma beda seratus perak.'},{q:"Efek digit kiri muncul kalau...",opts:["Harganya di atas Rp100.000","Angka paling kirinya berubah","Harganya genap","Selalu, di semua harga"],ans:1,why:"Rp49.900 vs Rp50.000 kena efeknya karena angka depannya berubah dari 4 ke 5. Kalau angka depannya sama, efeknya gak muncul."},{q:"Mana yang TIDAK kena efek digit kiri?",opts:["Rp49.900 vs Rp50.000","Rp48.900 vs Rp49.000","Rp99.000 vs Rp100.000","Rp9.900 vs Rp10.000"],ans:1,why:"Dua-duanya diawali angka 4. Karena angka paling kirinya gak berubah, otak gak ngerasa ada beda besar."}]},{dir:"12-tidur",cat:"Psikologi",head:"Tidur 6 jam tiap malam? Otakmu mungkin lagi kayak habis begadang.",chrome:"#060B17",pos:"55%",src:"Van Dongen dkk. 2003 (Sleep); konsensus AASM & Sleep Research Society 2015.",title:"Tidur 6 jam",slides:['"6 jam cukup lah." Banyak yang mikir gitu, apalagi pas lagi ngejar skripsi atau baru masuk kerja. Ternyata ada eksperimen yang ngetes ini beneran.',"Tahun 2003, peserta dibagi jadi beberapa grup. Ada yang tidur 8 jam, 6 jam, 4 jam, selama dua minggu penuh. Ada juga yang gak tidur sama sekali tiga hari. Tiap hari fokus dan daya pikir mereka dites.","Grup 6 jam makin hari makin turun. Di akhir dua minggu, hasil tes mereka setara sama orang yang gak tidur sampai dua malam.","Yang bikin kaget, mereka sendiri gak ngerasa separah itu. Ngantuknya naik di awal, habis itu ya biasa aja. Otaknya terus turun, orangnya ngerasa aman-aman aja.",'Jadi "aku baik-baik aja kok" itu gak bisa dijadikan patokan. Kalau lagi sering begadang buat lembur atau ngerjain tugas, bisa jadi hasilnya gak sebagus yang kamu kira.'],deep:`<h2>Tidur 6 jam, lebih dalam</h2>
<h3>Kenapa perasaan kita bisa salah</h3>
<p>Di studi itu, grup 6 jam sama grup 4 jam ngerasa sama ngantuknya. Padahal hasil tesnya beda jauh. Kita sering bilang "udah biasa tidur dikit". Yang biasa itu cuma perasaannya, otaknya sih enggak.</p>
<p>Asosiasi dokter tidur di Amerika nyaranin orang dewasa tidur minimal 7 jam semalam secara rutin. Jadi 6 jam itu memang udah di bawah batas.</p>
<p class="src">Sumber: Van Dongen dkk. 2003 (Sleep); konsensus AASM &amp; Sleep Research Society 2015.</p>`,quizzes:[{q:"Setelah 2 minggu tidur 6 jam per malam, performa otak peserta setara dengan...",opts:["Orang yang cukup tidur","Orang yang tidak tidur sampai 2 malam","Sedikit lebih buruk dari normal","Lebih baik karena terbiasa"],ans:1,why:"Setelah dua minggu tidur 6 jam per malam, hasil tes peserta setara dengan orang yang tidak tidur sampai dua malam."},{q:"Apa yang dirasakan peserta 6 jam soal rasa ngantuknya?",opts:["Makin ngantuk setiap hari","Naik di awal lalu datar, jadi mereka gak sadar seberapa menurun","Gak ngantuk sama sekali","Langsung pingsan"],ans:1,why:"Ngantuknya naik sebentar lalu terasa biasa aja, padahal hasil tesnya terus turun. Grup 6 jam bahkan ngerasa sama ngantuknya dengan grup 4 jam."},{q:"Pelajaran utama studi ini...",opts:["6 jam itu cukup",'Perasaan "baik-baik saja" bukan ukuran yang bisa dipercaya',"Tidur siang menggantikan tidur malam","Kopi menyelesaikan masalahnya"],ans:1,why:"Peserta merasa aman-aman aja padahal hasil tesnya terus menurun. Yang terbiasa itu cuma perasaannya, otaknya enggak."}]},{dir:"13-micin",cat:"Sains",head:"Takut micin? Awalnya cuma dari satu surat.",chrome:"#180505",pos:"50%",src:'Kwok 1968 (NEJM); Geha dkk. 2000, uji double-blind 130 orang; FDA, "Questions and Answers on MSG"; Olney 1969.',title:"Micin",slides:['"Jangan banyak-banyak micin, nanti pusing." Hampir semua orang pernah dengar. Tapi pernah kepikiran gak, sebenarnya ini dari mana asalnya?',"Tahun 1968, ada dokter di Amerika namanya Robert Ho Man Kwok. Dia nulis surat ke sebuah jurnal kedokteran. Isinya curhat: tiap habis makan di restoran Chinese, lehernya kebas dan badannya lemas. Dia nebak-nebak penyebabnya, mungkin MSG, mungkin arak masak, mungkin garam.",'Cuma tebakan, bukan penelitian. Tapi jurnalnya kasih judul "Chinese Restaurant Syndrome", dan istilah itu nyebar ke mana-mana. Lama-lama orang nganggap itu fakta.',"Akhirnya ada yang ngetes beneran. Tahun 2000, 130 orang yang ngaku sensitif MSG dites dengan cara double-blind: yang dites dan yang ngetes sama-sama gak tahu siapa yang dapat MSG, siapa yang dapat plasebo. Hasilnya, gejalanya gak muncul secara konsisten. Malah ada yang ngeluh pusing padahal cuma dapat plasebo.","Bukan berarti micin boleh sebanyak-banyaknya. Di beberapa tes ada juga sebagian kecil orang yang ngerasain gejala ringan. Tapi buat kebanyakan orang, micin dalam takaran wajar gak terbukti bikin pusing."],deep:`<h2>Micin, lebih dalam</h2>
<h3>Micin itu sebenarnya apa sih?</h3>
<p>Sekitar tahun 1908, ilmuwan Jepang namanya Kikunae Ikeda penasaran kenapa kaldu rumput laut kombu rasanya gurih banget. Ternyata gurihnya dari zat namanya glutamat. Rasa itu dia kasih nama umami, dan setahun kemudian dijual dengan merek Ajinomoto.</p>
<p>Glutamat ini juga ada secara alami di tomat dan keju. Badan pengawas makanan Amerika (FDA) bilang glutamat dari micin dan dari makanan itu secara kimia sama aja, dan tubuh memprosesnya dengan cara yang sama.</p>
<h3>Kok ada yang ngerasa pusing beneran?</h3>
<p>Namanya efek nocebo, kebalikan dari plasebo. Kalau kita udah yakin sesuatu bakal bikin sakit, badan kita lebih gampang ngerasa sakit. Makanya ada peserta yang pusing padahal cuma minum plasebo.</p>
<h3>Terus "generasi micin"?</h3>
<p>Ketakutan micin merusak otak itu asalnya dari penelitian tahun 1969. Waktu itu anak tikus disuntik MSG dosis besar banget. Lah, kita kan makan micin, bukan nyuntik. Penelitian yang ngasih MSG lewat makanan ke tikus gak nemuin kerusakan otak, dan otak juga punya semacam penyaring yang ngebatasi glutamat dari darah masuk ke otak. Sampai sekarang belum ada bukti meyakinkan kalau micin dari makanan bikin orang jadi bodoh.</p>
<p class="src">Sumber: Kwok 1968 (NEJM); Geha dkk. 2000, uji double-blind 130 orang; FDA, "Questions and Answers on MSG"; Olney 1969.</p>`,quizzes:[{q:'Ketakutan "micin bikin pusing" berawal dari...',opts:["Penelitian besar di Jepang","Surat pembaca seorang dokter tahun 1968","Peringatan dari WHO","Iklan pesaing micin"],ans:1,why:"Surat tahun 1968 itu cuma berisi tebakan pribadi. Waktu diuji double-blind, gejalanya tidak muncul secara konsisten."},{q:"Apa itu uji double-blind?",opts:["Peserta ditutup matanya saat mencicipi","Peserta dan peneliti sama-sama tidak tahu siapa yang dapat MSG dan siapa yang dapat plasebo","Uji yang diulang dua kali","Uji di dua negara berbeda"],ans:1,why:"Karena gak ada yang tahu siapa dapat apa, harapan peserta dan peneliti gak bisa mempengaruhi hasilnya."},{q:"Dalam uji tahun 2000 terhadap orang yang mengaku sensitif MSG, apa hasilnya?",opts:["Semua peserta merasa pusing","Gejalanya tidak muncul secara konsisten, bahkan ada yang mengeluh setelah minum plasebo","MSG terbukti berbahaya","Ujinya dibatalkan"],ans:1,why:"Gejalanya gak muncul secara konsisten. Ada yang pusing padahal cuma minum plasebo, ini yang disebut efek nocebo."}]},{dir:"14-bahasa",cat:"Sejarah",head:"Orang Jawa itu mayoritas. Kok bahasa nasionalnya bukan bahasa Jawa?",chrome:"#0C1007",pos:"55%",src:'Paauw 2009; Cambridge, "National language and nation-building"; Pasal 36 UUD 1945.',title:"Bahasa Indonesia",slides:["Tahun 1930, hampir setengah penduduk Hindia Belanda orang Jawa. Kalau mau gampang, ya pakai aja bahasa Jawa jadi bahasa nasional. Tapi yang dipilih justru bahasa Melayu, yang jadi dasar bahasa Indonesia.","Bahasa Melayu udah ratusan tahun jadi bahasa dagang di pelabuhan-pelabuhan Nusantara. Pedagang dari Sumatra, Maluku, Sulawesi, sampai Tiongkok pakai Melayu buat ngobrol dan tawar-menawar. Jadi banyak orang dari berbagai pulau udah familiar.","Bahasa Jawa punya tingkatan: ngoko buat teman, krama buat orang yang lebih tua atau dihormati. Salah pilih kata bisa dianggap gak sopan. Buat orang luar Jawa, ini susah dipelajari.",'Bahasa Melayu lebih "rata". Gak ada tingkatan serumit itu, jadi gak terasa ada yang lebih tinggi atau lebih rendah. Dan karena bukan bahasa suku terbesar, gak ada kesan satu suku menguasai yang lain.',"Tahun 1928, para pemuda di Sumpah Pemuda berikrar menjunjung bahasa persatuan, bahasa Indonesia. Waktu itu belum jadi bahasa resmi negara, karena negaranya juga belum ada. Statusnya sebagai bahasa negara baru ditetapkan setelah merdeka."],deep:`<h2>Bahasa Indonesia, lebih dalam</h2>
<h3>Pengorbanan dari mayoritas?</h3>
<p>Ada sejarawan, salah satunya Benedict Anderson, yang melihat pilihan ini sebagai bentuk "mengalah" dari orang Jawa. Tapi ada juga peneliti yang nyatat kalau pandangan ini kebanyakan disampaikan orang Jawa sendiri belakangan. Jadi anggap ini salah satu tafsiran, bukan fakta yang disepakati semua orang.</p>
<p>Yang jelas, keputusan ini bikin Indonesia beda dari banyak negara lain: bahasa nasionalnya bukan bahasa suku terbesar, dan justru karena itu bisa diterima banyak suku.</p>
<p class="src">Sumber: Paauw 2009; Cambridge, "National language and nation-building"; Pasal 36 UUD 1945.</p>`,quizzes:[{q:"Salah satu alasan bahasa Melayu dipilih jadi dasar bahasa Indonesia adalah...",opts:["Paling banyak penuturnya","Sudah lama jadi bahasa dagang antarpulau","Dipaksa Belanda","Paling mirip bahasa Inggris"],ans:1,why:"Bahasa Melayu sudah ratusan tahun dipakai pedagang dari berbagai pulau, jadi banyak orang sudah familiar."},{q:"Kenapa bahasa Jawa dianggap sulit jadi bahasa bersama?",opts:["Hurufnya berbeda","Punya tingkatan bahasa (ngoko–krama) yang rumit dan hierarkis","Penuturnya sedikit","Tidak punya kosakata modern"],ans:1,why:"Ada ngoko buat teman dan krama buat orang yang lebih tua atau dihormati. Salah pilih kata bisa dianggap gak sopan, dan ini susah dipelajari orang luar Jawa."},{q:"Sumpah Pemuda 1928 menyatakan bahasa Indonesia sebagai...",opts:["Bahasa resmi negara","Bahasa persatuan","Bahasa daerah","Bahasa asing wajib"],ans:1,why:"Waktu itu belum jadi bahasa resmi negara, karena negaranya juga belum ada. Statusnya sebagai bahasa negara baru ditetapkan setelah merdeka."}]},{dir:"15-wallace",cat:"Sains",head:"Bali dan Lombok cuma dipisah selat sempit, tapi hewannya beda “benua”.",chrome:"#030A18",pos:"18%",src:"Catatan Wallace; esai Ternate 1858; Linnean Society, 1 Juli 1858.",title:"Garis Wallace",slides:["Dari Bali ke Lombok naik kapal cepat cuma sebentar. Jaraknya cuma sekitar 35 kilometer. Tapi hewan di dua pulau ini bedanya jauh banget.","Di Bali ada burung-burung yang kerabatnya di Asia, misalnya burung pelatuk. Waktu nyeberang ke Lombok, naturalis Inggris Alfred Russel Wallace nyatat burung-burung itu menghilang, dan gantinya muncul burung yang kerabatnya di Australia, seperti kakatua.","Wallace keliling Nusantara di pertengahan 1800-an. Garis pemisah yang dia temukan itu sekarang dikenal sebagai Garis Wallace.","Kenapa bisa gitu? Waktu zaman es, permukaan laut turun sampai sekitar 120 meter. Sumatra, Jawa, dan Bali nyambung jadi satu daratan dengan Asia, jadi hewan bisa jalan kaki ke sana.","Tapi Selat Lombok itu dalam banget, lebih dalam dari turunnya laut waktu itu. Jadi selatnya tetap jadi laut, dan hewan darat dari Asia gak bisa nyeberang ke timur."],deep:`<h2>Garis Wallace, lebih dalam</h2>
<h3>Teori evolusi juga lahir di Nusantara</h3>
<p>Wallace bukan cuma nemuin garis ini. Tahun 1858, waktu lagi di Ternate, Maluku, dia nulis esai tentang bagaimana spesies bisa berubah lewat seleksi alam, terus dikirim ke Charles Darwin.</p>
<p>Darwin kaget, karena idenya mirip banget sama teori yang udah lama dia kerjakan diam-diam. Akhirnya tulisan Wallace dan Darwin dibacakan bareng di pertemuan ilmiah di London pada Juli 1858.</p>
<p>Jadi salah satu teori paling penting dalam sains modern sebagian ditulis di Maluku.</p>
<p class="src">Sumber: Catatan Wallace; esai Ternate 1858; Linnean Society, 1 Juli 1858.</p>`,quizzes:[{q:"Kenapa hewan di Bali dan Lombok bisa sangat berbeda?",opts:["Iklimnya beda jauh","Selat Lombok terlalu dalam, jadi tetap laut waktu zaman es","Hewannya dipindahkan manusia","Lombok lebih tinggi dari Bali"],ans:1,why:"Waktu zaman es, laut turun sekitar 120 meter, tapi Selat Lombok lebih dalam dari itu, jadi tetap jadi laut dan hewan darat tidak bisa menyeberang."},{q:"Waktu zaman es, Bali tersambung dengan...",opts:["Australia","Jawa, Sumatra, dan daratan Asia","Lombok","Papua"],ans:1,why:"Laut turun sekitar 120 meter, jadi Sumatra, Jawa, dan Bali nyambung jadi satu daratan dengan Asia. Hewan bisa jalan kaki ke sana."},{q:"Di mana Wallace menulis esainya tentang seleksi alam yang dikirim ke Darwin?",opts:["London","Bali","Ternate","Galapagos"],ans:2,why:"Tahun 1858 Wallace lagi di Ternate, Maluku. Dari sana dia nulis esai soal seleksi alam dan ngirimnya ke Charles Darwin."}]},{dir:"16-investasi",cat:"Finansial",head:"Investasi bodong pasti bayar di awal. Ada alasannya.",chrome:"#090704",pos:"22%",src:"OJK (Rp142,22 triliun, 2017–Q3 2025); prinsip 2L OJK.",title:"Investasi bodong",slides:['Temanmu cerita, "Gue ikut investasi, tiap minggu cuan masuk. Udah tiga bulan lancar." Transferannya ada, buktinya nyata. Aman dong? Tunggu dulu.',"Tahun 1920, ada orang Amerika namanya Charles Ponzi. Dia janjiin untung 50% dalam 45 hari, katanya dari main selisih harga kupon pos antarnegara. Ribuan orang ikut, dan di awal mereka beneran dibayar.",'Masalahnya, duit buat bayar "untung" itu asalnya dari setoran orang-orang yang baru gabung. Bisnis kuponnya sendiri nyaris gak ada. Pas diaudit, kupon yang dia pegang jauh lebih sedikit dari yang dia klaim.',"Makanya skema kayak gini rajin bayar di awal. Orang yang udah dapat cuan bakal cerita ke teman dan keluarga, terus mereka ikut. Tapi skemanya butuh orang baru terus. Begitu yang gabung mulai seret, langsung ambruk, dan yang paling rugi biasanya yang masuk paling akhir.",'Di Indonesia, OJK nyatat kerugian masyarakat gara-gara investasi ilegal mencapai Rp142,22 triliun dari 2017 sampai kuartal III 2025. Itu gabungan semua jenis investasi ilegal, bukan Ponzi doang, tapi pola "bayar dulu, ajak teman" muncul lagi dan lagi.'],deep:`<h2>Investasi bodong, lebih dalam</h2>
<h3>Kok Ponzi bisa ketahuan?</h3>
<p>Ada yang ngitung, kalau klaim Ponzi beneran, dia butuh kupon jauh lebih banyak dari yang beredar di seluruh dunia. Terus koran Boston Post mulai nyelidikin. Investor panik, rame-rame narik duit, dan skemanya runtuh. Beberapa bank di Boston sampai ikut tumbang.</p>
<p>Tanda-tanda yang patut dicurigai:</p>
<ul><li>Janji untung gede, "pasti", katanya gak ada risiko</li><li>Makin banyak ngajak orang, makin gede cuannya</li><li>Kalau ditanya duitnya diputar di mana, jawabannya muter-muter</li></ul>
<p>Sebelum ikut investasi apa pun, ingat 2L dari OJK: Legal dan Logis.</p>
<ul><li>Legal: cek izinnya di OJK. Perusahaannya punya izin PT belum tentu boleh ngumpulin duit orang.</li><li>Logis: investasi resmi biasanya ngasih untung sekitar 3–10% setahun. Kalau ada yang janjiin 50% sebulan, itu udah gak masuk akal.</li></ul>
<p class="src">Sumber: OJK (Rp142,22 triliun, 2017–Q3 2025); prinsip 2L OJK.</p>`,quizzes:[{q:'Dalam skema Ponzi, "keuntungan" investor lama dibayar dari...',opts:["Hasil bisnis yang nyata","Uang investor baru","Bunga bank","Subsidi pemerintah"],ans:1,why:'Dalam skema Ponzi, "keuntungan" investor lama dibayar pakai setoran investor baru, bukan dari bisnis yang nyata.'},{q:"Kenapa skema Ponzi rajin membayar di awal?",opts:["Karena bisnisnya memang untung","Supaya investor percaya dan mengajak orang lain","Karena diwajibkan hukum","Kebetulan saja"],ans:1,why:"Orang yang udah dapat cuan bakal cerita ke teman dan keluarga, lalu mereka ikut. Uang dari orang baru itulah yang dipakai buat bayar orang lama."},{q:"Kapan skema Ponzi runtuh?",opts:["Setelah tepat 1 tahun","Saat investor baru yang masuk melambat","Saat harga emas naik","Tidak pernah runtuh"],ans:1,why:"Skemanya butuh uang orang baru terus. Begitu yang gabung mulai seret, gak ada lagi yang bisa dibayarkan, dan yang paling rugi biasanya yang masuk belakangan."}]},{dir:"17-sorotan",cat:"Psikologi",head:"Kamu ngerasa semua orang ngeliatin. Kenyataannya, gak sebanyak itu.",chrome:"#260A08",pos:"28%",src:"Gilovich, Medvec & Savitsky 2000 (JPSP); Savitsky & Gilovich 2003.",title:"Efek sorotan",slides:["Salah ngomong waktu presentasi, atau datang ke kampus pakai baju yang ternyata salah kostum. Rasanya semua orang ngeliatin dan bakal inget terus. Beneran gitu?","Tahun 2000, peneliti di Cornell nyuruh mahasiswa pakai kaos bergambar penyanyi yang dianggap norak, terus masuk ke ruangan yang penuh mahasiswa lain.","Habis itu mereka disuruh nebak berapa orang di ruangan yang sadar sama kaosnya. Tebakan mereka sekitar separuh ruangan. Kenyataannya, cuma sekitar seperempat.","Ini namanya efek sorotan. Kita ngerasa ada lampu sorot yang ngikutin kita ke mana-mana, padahal orang lain lagi sibuk mikirin dirinya sendiri.","Lucunya, efek ini juga muncul waktu kaosnya biasa aja. Jadi bukan cuma soal malu. Kita memang cenderung ngerasa jadi pusat perhatian."],deep:`<h2>Efek sorotan, lebih dalam</h2>
<h3>Ilusi "kelihatan banget"</h3>
<p>Ada efek yang mirip, namanya ilusi transparansi. Kita ngerasa rasa gugup kita kelihatan jelas dari luar. Padahal orang lain sering gak bisa nebak sebanyak yang kita kira.</p>
<p>Di penelitian tahun 2003, orang disuruh pidato dadakan. Sebagian dikasih tahu soal ilusi ini sebelum pidato: penonton biasanya gak sadar segugup apa kamu. Hasilnya, kelompok ini ngerasa lebih tenang, dan penonton juga menilai mereka lebih percaya diri.</p>
<h3>Terus gunanya buat apa?</h3>
<p>Waktu mau presentasi, interview, atau salah ngomong di grup, ingat aja dua hal:</p>
<ul><li>Orang lain lebih sedikit merhatiin kamu daripada yang kamu kira.</li><li>Gugupmu gak sekelihatan yang kamu rasain.</li></ul>
<p>Bukan berarti gak ada yang peduli. Cuma, lampu sorotnya gak seterang yang kamu bayangin.</p>
<p class="src">Sumber: Gilovich, Medvec &amp; Savitsky 2000 (JPSP); Savitsky &amp; Gilovich 2003.</p>`,quizzes:[{q:"Di eksperimen kaos tahun 2000, peserta menebak separuh ruangan sadar kaosnya. Kenyataannya...",opts:["Hampir semua orang sadar","Cuma sekitar seperempat yang sadar","Tidak ada yang sadar sama sekali","Persis separuh ruangan"],ans:1,why:"Tebakannya sekitar separuh, kenyataannya cuma sekitar seperempat. Kita cenderung ngerasa jadi pusat perhatian, padahal orang lain sibuk sama dirinya sendiri."},{q:"Apa yang terjadi pada pembicara yang dikasih tahu soal ilusi transparansi sebelum pidato?",opts:["Mereka jadi makin gugup","Mereka lebih tenang dan dinilai lebih percaya diri oleh penonton","Tidak ada bedanya sama sekali","Mereka menolak pidato"],ans:1,why:"Tahu bahwa gugup gak sekelihatan itu bikin mereka lebih santai, dan penonton pun melihat mereka lebih percaya diri."},{q:"Efek sorotan tetap muncul walaupun kaosnya...",opts:["Mahal","Biasa saja, tidak memalukan","Dipakai terbalik","Berwarna hitam"],ans:1,why:"Efeknya bukan cuma soal malu. Kita memang cenderung mengira diri kita lebih diperhatikan daripada kenyataannya."}]},{dir:"18-kafein",cat:"Sains",head:"Kopi gak ngasih kamu energi. Dia cuma ngumpetin rasa capeknya.",chrome:"#27170C",pos:"28%",src:"Fredholm dkk. 1999; Drake dkk. 2013 (J Clin Sleep Med).",title:"Kafein",slides:["Ngantuk jam dua siang, langsung beli es kopi susu. Setengah jam kemudian melek lagi. Kerasa kayak dapat energi tambahan. Padahal bukan itu yang terjadi.","Selama kita bangun, otak ngumpulin zat namanya adenosin. Makin lama melek, makin banyak adenosin, makin ngantuk. Ini semacam alarm alami bahwa otak butuh istirahat.","Nah, kafein bentuknya mirip adenosin. Dia nempel di tempat yang biasanya ditempati adenosin, jadi sinyal ngantuknya gak nyampe. Kafein gak ngebuang adenosinnya, cuma ngehalangin.","Masalahnya, adenosin tetap numpuk di belakang. Begitu efek kafeinnya habis, sinyal capek yang ketahan tadi bisa kerasa lagi sekaligus.","Dan kafein itu awet. Di tubuh orang dewasa, butuh sekitar lima jam rata-rata buat ngilangin setengahnya. Jadi kopi jam empat sore masih kerja waktu kamu mau tidur."],deep:`<h2>Kafein, lebih dalam</h2>
<h3>Kopi sore beneran ngaruh ke tidur?</h3>
<p>Tahun 2013, peneliti ngasih peserta kafein dosis besar (400 mg) di tiga waktu: pas mau tidur, tiga jam sebelumnya, dan enam jam sebelumnya. Bahkan yang enam jam sebelum tidur, total tidurnya berkurang lebih dari satu jam.</p>
<p>Yang bikin kaget, banyak peserta gak ngerasa tidurnya keganggu. Alatnya nyatat beda, perasaannya bilang aman. Mirip sama topik tidur 6 jam: perasaan "baik-baik aja" bukan ukuran yang bisa dipercaya.</p>
<h3>Kenapa efeknya beda-beda tiap orang?</h3>
<p>Kecepatan tubuh ngurai kafein beda-beda. Sebagian besar kerjanya dilakuin enzim di hati, dan enzim ini dipengaruhi gen, umur, obat, sampai kondisi hati. Jadi ada orang yang ngopi malam masih bisa tidur, ada yang ngopi siang aja udah susah tidur.</p>
<p>Kalau kamu sering susah tidur, coba cek jam kopi terakhirmu. Banyak saran tidur nyebut berhenti ngopi sekitar enam jam sebelum tidur.</p>
<p class="src">Sumber: Fredholm dkk. 1999; Drake dkk. 2013 (J Clin Sleep Med).</p>`,quizzes:[{q:"Gimana cara kafein bikin kita melek?",opts:["Nambah energi langsung ke otot","Ngehalangin sinyal ngantuk dari adenosin","Ngebuang adenosin dari otak","Naikin gula darah"],ans:1,why:"Kafein nempel di tempat yang biasanya ditempati adenosin, jadi sinyal ngantuknya gak nyampe. Adenosinnya sendiri tetap ada."},{q:"Butuh berapa lama rata-rata tubuh orang dewasa ngilangin setengah kafein?",opts:["Sekitar 30 menit","Sekitar 5 jam","Sekitar 2 hari","Langsung habis begitu efeknya hilang"],ans:1,why:"Rata-ratanya sekitar lima jam, tapi bisa jauh lebih cepat atau lebih lama tergantung orangnya. Makanya kopi sore masih kerja waktu malam."},{q:"Di penelitian 2013, kafein yang diminum 6 jam sebelum tidur...",opts:["Tidak berpengaruh sama sekali","Tetap mengurangi tidur lebih dari satu jam","Bikin tidur lebih nyenyak","Cuma berpengaruh ke orang tua"],ans:1,why:"Total tidurnya berkurang lebih dari satu jam, padahal banyak peserta gak ngerasa tidurnya keganggu."}]},{dir:"19-cabai",cat:"Sains",head:"Sambal gak beneran panas. Otakmu yang ketipu.",chrome:"#253834",pos:"28%",src:"Nobel Kedokteran 2021 (Julius & Patapoutian); Nolden & Hayes 2019.",title:"Cabai",slides:['Makan seblak level lima, mulut rasanya kebakar, keringetan, hidung meler. Tapi suhu seblaknya ya biasa aja. Terus "panas"-nya dari mana?',"Di lidah dan mulut kita ada sensor yang tugasnya ngedeteksi panas yang berbahaya, sekitar di atas 43 derajat Celsius. Kalau kena, dia kirim sinyal ke otak: awas, panas!",'Zat pedas di cabai namanya capsaicin. Dia bisa nyalain sensor yang sama, padahal suhunya gak naik sama sekali. Jadi otak nerima sinyal "panas" dan badan bereaksi kayak lagi kepanasan.',"Penemuan sensor ini bahkan dapat Hadiah Nobel Kedokteran tahun 2021. Peneliti David Julius nemuinnya justru dengan pakai capsaicin, zat dari cabai.","Jadi rasa pedas itu sebenarnya bukan rasa, kayak manis atau asin. Itu sinyal panas palsu."],deep:`<h2>Cabai, lebih dalam</h2>
<h3>Kenapa air gak mempan?</h3>
<p>Capsaicin gak larut di air. Minum air dingin cuma kerasa adem sebentar, capsaicinnya tetap nempel.</p>
<p>Tahun 2019 ada penelitian yang ngebandingin beberapa minuman buat ngeredain pedas. Susu, baik susu biasa maupun skim, termasuk yang paling ngebantu, sedangkan air hampir gak ngefek. Penelitian lain nyebut protein susu namanya kasein ikut berperan, walaupun hasilnya belum seragam.</p>
<h3>Kok ada orang yang "kebal" pedas?</h3>
<p>Kalau sering kena capsaicin, sensornya bisa jadi kurang peka. Makanya orang yang tiap hari makan sambal bisa santai makan level yang bikin orang lain nangis.</p>
<p>Sifat ini malah dipakai di dunia medis. Ada koyo dan krim capsaicin buat ngeredain nyeri tertentu, karena sensor yang udah kurang peka ngirim sinyal nyeri lebih sedikit.</p>
<p class="src">Sumber: Nobel Kedokteran 2021 (Julius &amp; Patapoutian); Nolden &amp; Hayes 2019.</p>`,quizzes:[{q:'Kenapa makan sambal terasa "panas"?',opts:["Sambal memang menaikkan suhu mulut","Capsaicin menyalakan sensor panas, padahal suhunya tidak naik","Lidah terluka karena cabai","Karena cabai mengandung minyak panas"],ans:1,why:'Capsaicin nyalain sensor yang biasanya bereaksi ke panas berbahaya. Otak nerima sinyal "panas" walaupun suhunya biasa aja.'},{q:"Kenapa minum air kurang ampuh ngeredain pedas?",opts:["Airnya kurang dingin","Capsaicin tidak larut di air","Air bikin cabai makin pedas","Air malah memanaskan mulut"],ans:1,why:"Capsaicin gak larut di air, jadi tetap nempel. Di penelitian 2019, susu termasuk yang paling ngebantu, air hampir gak ngefek."},{q:"Penemuan sensor panas yang dipicu capsaicin mendapat...",opts:["Hadiah Nobel Kimia 1990","Hadiah Nobel Kedokteran 2021","Penghargaan dari WHO","Belum diakui"],ans:1,why:"David Julius dapat Nobel Kedokteran 2021, salah satunya karena nemuin sensor ini dengan bantuan capsaicin dari cabai."}]},{dir:"20-dunning-kruger",cat:"Psikologi",head:"Yang paling pede justru paling gak ngerti? Ternyata gak sesederhana itu.",chrome:"#121617",pos:"28%",src:"Kruger & Dunning 1999 (JPSP); Nuhfer dkk. 2016–2017; Magnus & Peresetsky 2022.",title:"Dunning-Kruger",slides:['Pernah lihat grafik yang naik tajam, jatuh, lalu naik pelan, katanya "orang yang baru belajar dikit merasa paling pinter"? Itu sering disebut efek Dunning-Kruger. Tapi grafik itu gak ada di penelitian aslinya.',"Penelitian aslinya tahun 1999. Mahasiswa dites soal logika, tata bahasa, dan humor, terus disuruh nebak peringkat mereka sendiri dibanding teman-temannya.","Kelompok yang nilainya paling rendah rata-rata ada di peringkat bawah, sekitar persentil 12. Tapi mereka nebak dirinya di atas rata-rata, sekitar persentil 62.",'Belakangan, beberapa peneliti nunjukin kalau pola grafik mirip bisa muncul dari data acak. Orang yang nilainya paling bawah gampang kelihatan "kepedean", karena ruang buat salah nebak ke atas jauh lebih luas.','Jadi efeknya mungkin ada, tapi sebagian bisa jadi efek statistik. Dan yang jelas, ini bukan bukti bahwa "orang bodoh pasti sombong".'],deep:`<h2>Dunning-Kruger, lebih dalam</h2>
<h3>Yang sering salah dipahami</h3>
<p>Efek Dunning-Kruger aslinya soal kemampuan tertentu, bukan soal pintar atau bodoh secara umum. Orang yang jago masak bisa aja kepedean soal investasi.</p>
<p>Grafik "gunung kebodohan" yang sering beredar di media sosial juga bukan dari penelitian 1999. Grafik penelitian aslinya cuma garis nilai sebenarnya dibandingkan garis tebakan.</p>
<h3>Perdebatan peneliti</h3>
<p>Tahun 2016 dan 2017, Nuhfer dan rekan-rekannya bikin simulasi pakai angka acak dan dapat pola yang mirip. Ada juga peneliti lain di tahun 2022 yang bilang polanya bisa dijelaskan karena nilai tes ada batas atas dan bawahnya.</p>
<p>Di sisi lain, Kruger dan Dunning bilang penjelasan statistik gak bisa menjelaskan semua hasil eksperimen mereka. Sampai sekarang perdebatannya belum selesai.</p>
<p>Pelajarannya: konsep yang terdengar meyakinkan dan viral pun tetap perlu dicek. Termasuk konsep tentang orang yang gak sadar dirinya salah.</p>
<p class="src">Sumber: Kruger &amp; Dunning 1999 (JPSP); Nuhfer dkk. 2016–2017; Magnus &amp; Peresetsky 2022.</p>`,quizzes:[{q:"Di penelitian 1999, kelompok dengan nilai terendah menebak peringkat mereka sendiri di sekitar...",opts:["Persentil 12, sesuai kenyataan","Persentil 62, di atas rata-rata","Persentil 99, paling atas","Mereka menolak menebak"],ans:1,why:"Aslinya mereka ada di sekitar persentil 12, tapi nebak dirinya di sekitar persentil 62."},{q:'Grafik "naik tajam, jatuh, lalu naik pelan" yang viral itu...',opts:["Grafik asli dari penelitian 1999","Tidak ada di penelitian aslinya","Dibuat oleh Kruger tahun 2016","Hasil survei di Indonesia"],ans:1,why:"Grafik penelitian aslinya cuma garis nilai sebenarnya dibandingkan garis tebakan. Bentuk gunung itu muncul belakangan di internet."},{q:"Kritik utama terhadap efek Dunning-Kruger adalah...",opts:["Penelitiannya tidak pernah dilakukan","Pola yang mirip bisa muncul dari data acak","Pesertanya terlalu sedikit","Kruger dan Dunning mengakui penelitiannya salah"],ans:1,why:"Simulasi pakai angka acak bisa ngasilin pola yang mirip. Kruger dan Dunning membantahnya, dan perdebatannya belum selesai."}]},{dir:"21-gunting",cat:"Sejarah",head:"Tahun 1950, uang kertas kita pernah digunting jadi dua. Beneran.",chrome:"#190602",pos:"28%",src:"Museum Bank Indonesia; Perpu No. 2 Tahun 1959.",title:"Gunting Sjafruddin",slides:["Bayangin kamu bangun pagi, terus dengar pengumuman: uang kertas kamu harus digunting jadi dua. Bukan kiasan, beneran pakai gunting. Ini kejadian di Indonesia, Maret 1950.","Waktu itu Indonesia baru merdeka dan keuangannya kacau. Uang yang beredar terlalu banyak, harga-harga naik, dan anggaran negara tekor.","Menteri Keuangan Sjafruddin Prawiranegara ambil langkah nekat. Uang kertas pecahan besar digunting. Separuh kiri masih boleh dipakai belanja, tapi nilainya tinggal setengah.","Separuh kanan gak bisa dipakai belanja. Potongan itu bisa ditukar dengan surat utang pemerintah, yang janjinya dibayar 40 tahun kemudian dengan bunga 3% setahun.","Jadi dalam semalam, uang tunai orang-orang yang pegang pecahan besar langsung tinggal setengah. Kebijakan ini dikenal sebagai Gunting Sjafruddin."],deep:`<h2>Gunting Sjafruddin, lebih dalam</h2>
<h3>Kenapa harus digunting?</h3>
<p>Tujuannya ngurangin jumlah uang yang beredar biar harga gak terus naik, sekaligus nutup defisit anggaran. Gunting jadi cara cepat buat narik separuh uang tunai dari masyarakat.</p>
<p>Yang paling kena tentu orang yang nyimpen banyak uang tunai pecahan besar.</p>
<h3>Bukan yang terakhir</h3>
<p>Tahun 1959 ada kebijakan yang mirip, namanya sanering. Mulai 25 Agustus 1959, uang Rp500 nilainya diturunkan jadi Rp50, dan Rp1.000 jadi Rp100. Pemiliknya kehilangan 90% nilai uangnya, sementara harga barang gak ikut turun.</p>
<p>Ini beda sama redenominasi yang kadang dibahas sekarang. Redenominasi cuma motong nol di uang dan di harga dengan perbandingan yang sama. Jadi kalau Rp1.000 jadi Rp1, harga barang Rp10.000 juga jadi Rp10. Daya beli gak berubah.</p>
<p class="src">Sumber: Museum Bank Indonesia; Perpu No. 2 Tahun 1959.</p>`,quizzes:[{q:"Apa yang terjadi pada separuh kiri uang yang digunting tahun 1950?",opts:["Langsung tidak berlaku","Masih bisa dipakai belanja dengan nilai setengah","Nilainya jadi dua kali lipat","Ditukar dengan emas"],ans:1,why:"Separuh kiri tetap berlaku sebagai uang, tapi nilainya tinggal setengah. Separuh kanan bisa ditukar dengan surat utang pemerintah."},{q:"Separuh kanan uang yang digunting bisa ditukar dengan...",opts:["Beras","Surat utang pemerintah yang dibayar 40 tahun kemudian","Uang logam","Tidak bisa ditukar apa pun"],ans:1,why:"Potongan kanan bisa ditukar dengan obligasi pemerintah. Janjinya dibayar 40 tahun kemudian dengan bunga 3% setahun."},{q:"Apa beda sanering 1959 dengan redenominasi?",opts:["Tidak ada bedanya","Sanering memotong nilai uang tanpa menurunkan harga barang","Redenominasi membuat orang kehilangan 90% uangnya","Sanering hanya berlaku untuk uang logam"],ans:1,why:"Di sanering 1959, Rp1.000 jadi Rp100 tapi harga barang tetap. Di redenominasi, nol di uang dan di harga dipotong sama-sama, jadi daya beli gak berubah."}]}],G=$a,O=a=>G.find(n=>n.dir===a),ca="./",B=(a,n)=>`${ca}img/${a}/${n}.webp`,Wa=a=>`${ca}music/${a}.mp3`,ja="brainrocks.v1",fa=864e5,ga=[3,7,30],Ua=Number(new URLSearchParams(location.search).get("hari"))||0,ea=()=>Date.now()+Ua*fa;function wa(){return{v:1,order:G.map(a=>a.dir),rec:{}}}function Fa(){try{const a=JSON.parse(localStorage.getItem(ja)||"null");if(a&&a.v===1){const n=new Set(G.map(e=>e.dir));a.order=a.order.filter(e=>n.has(e));for(const e of n)a.order.includes(e)||a.order.push(e);return a}}catch{}return wa()}let p=Fa();function H(){try{localStorage.setItem(ja,JSON.stringify(p))}catch{}}const Sa=a=>p.rec[a],$=()=>Object.entries(p.rec).map(([a,n])=>({dir:a,...n})),ia=()=>p.order.filter(a=>!p.rec[a]);function Ya(a){p.order=p.order.filter(n=>n!==a).concat(a),H()}function Qa(a){p.rec[a]||(p.rec[a]={status:"disimpan",step:0,due:null,nextQ:0}),H()}